const fn = new Function(code + "\nreturn { joinPlan, txDecision, countQueries };");
const { joinPlan } = fn();
if (joinPlan("users and their tasks (skip users with none)") !== "inner") throw new Error("Only matched rows => inner.");
if (joinPlan("all users with task counts (zero included)") !== "left") throw new Error("Zeros included => left.");
if (joinPlan("all tasks with their tag names") !== "inner-two") throw new Error("Junction table => two joins.");

const fn = new Function(code + "\nreturn { joinPlan, txDecision, countQueries };");
const { txDecision } = fn();
if (txDecision(1, false) !== "single") throw new Error("One write, no risk => single.");
if (txDecision(2, false) !== "transaction") throw new Error("Two writes => atomic.");
if (txDecision(0, false) !== "readonly") throw new Error("No writes => readonly.");
if (txDecision(1, true) !== "transaction") throw new Error("Risk => wrap it.");

const fn = new Function(code + "\nreturn { joinPlan, txDecision, countQueries };");
const { countQueries } = fn();
if (countQueries(50, "n+1") !== 51) throw new Error("50 tasks + 1 list query = 51.");
if (countQueries(50, "join") !== 1) throw new Error("A join is one query.");
if (countQueries(50, "in-clause") !== 2) throw new Error("List + batched fetch = 2.");
